-- Creates the payment_attempts table: each execution of a payment intent
-- against one processor account. It belongs to the payments module.
--
-- An attempt is inserted as EXECUTING, with its operation_id, before the
-- provider is called (Reserve), and its result is applied afterwards by a
-- conditional update that requires the expected status (Apply). Timestamps
-- have no database default: the application supplies them from its injected
-- clock. Identifiers are UUIDs generated by the application.

CREATE TABLE payment_attempts (
  id uuid NOT NULL,
  merchant_id uuid NOT NULL,
  payment_intent_id uuid NOT NULL,
  processor_account_id uuid NOT NULL,
  -- Stable identity of the provider operation, created before the call: it is
  -- sent as the provider's idempotency key and is the lookup key for recovery.
  operation_id uuid NOT NULL,
  -- The idempotency record that the confirmation claimed. It stays in progress
  -- while the attempt is REQUIRES_ACTION or UNKNOWN, and the code that resolves
  -- the attempt completes it through this identity. No foreign key: the
  -- idempotency module owns its records and may purge completed ones after
  -- their expiry.
  idempotency_record_id uuid NOT NULL,
  status varchar(20) NOT NULL,
  provider_transaction_id varchar(255),
  decline_code varchar(64),
  error_category varchar(20),
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT payment_attempts_pkey PRIMARY KEY (id),
  -- Target of the composite foreign keys of later tables, such as refunds.
  CONSTRAINT payment_attempts_merchant_id_id_key UNIQUE (merchant_id, id),
  CONSTRAINT payment_attempts_operation_id_key UNIQUE (operation_id),
  -- The intent and the account of an attempt always belong to its merchant.
  CONSTRAINT payment_attempts_payment_intent_fkey FOREIGN KEY (merchant_id, payment_intent_id)
    REFERENCES payment_intents (merchant_id, id),
  CONSTRAINT payment_attempts_processor_account_fkey FOREIGN KEY (merchant_id, processor_account_id)
    REFERENCES processor_accounts (merchant_id, id),
  -- A provider transaction ID is unique only within its provider account.
  CONSTRAINT payment_attempts_provider_transaction_key UNIQUE (processor_account_id, provider_transaction_id),
  CONSTRAINT payment_attempts_status_check CHECK (
    status IN ('EXECUTING', 'REQUIRES_ACTION', 'SUCCEEDED', 'DECLINED', 'FAILED', 'UNKNOWN')
  ),
  CONSTRAINT payment_attempts_provider_transaction_id_check CHECK (provider_transaction_id ~ '^[!-~]{1,255}$'),
  CONSTRAINT payment_attempts_decline_code_check CHECK (decline_code ~ '^[a-z0-9_]{1,64}$'),
  -- The values mirror PROCESSOR_ERROR_CATEGORIES in packages/processor-contracts.
  CONSTRAINT payment_attempts_error_category_check CHECK (
    error_category IN ('CONFIGURATION', 'NETWORK', 'GATEWAY', 'ISSUER_DECLINE', 'INVALID_REQUEST', 'UNKNOWN')
  ),
  -- A charge and a pending customer action are always identified at the provider.
  CONSTRAINT payment_attempts_provider_transaction_required_check CHECK (
    status NOT IN ('REQUIRES_ACTION', 'SUCCEEDED') OR provider_transaction_id IS NOT NULL
  ),
  CONSTRAINT payment_attempts_decline_code_status_check CHECK (decline_code IS NULL OR status = 'DECLINED'),
  -- An unsuccessful or uncertain attempt says why; the others carry no category.
  CONSTRAINT payment_attempts_error_category_status_check CHECK (
    (status IN ('DECLINED', 'FAILED', 'UNKNOWN')) = (error_category IS NOT NULL)
  )
);

-- No second attempt of an intent while one may still charge or is waiting for
-- the customer: EXECUTING, REQUIRES_ACTION, and UNKNOWN attempts are open.
CREATE UNIQUE INDEX payment_attempts_one_open_per_intent_idx
  ON payment_attempts (payment_intent_id)
  WHERE status IN ('EXECUTING', 'REQUIRES_ACTION', 'UNKNOWN');

-- At most one successful attempt per intent.
CREATE UNIQUE INDEX payment_attempts_one_succeeded_per_intent_idx
  ON payment_attempts (payment_intent_id)
  WHERE status = 'SUCCEEDED';

-- The attempts of one intent, oldest first.
CREATE INDEX payment_attempts_merchant_id_payment_intent_id_created_at_id_idx
  ON payment_attempts (merchant_id, payment_intent_id, created_at, id);

COMMENT ON TABLE payment_attempts IS 'Executions of payment intents against processor accounts. Rows are never deleted, and a finished attempt never changes.';
COMMENT ON COLUMN payment_attempts.operation_id IS 'Provider idempotency key of the attempt, created before the provider call.';
COMMENT ON COLUMN payment_attempts.provider_transaction_id IS 'Identifier of the transaction at the provider, for example a Stripe pi_ ID. Never a client secret.';
COMMENT ON COLUMN payment_attempts.decline_code IS 'The provider decline code of a DECLINED attempt, when the provider gives one.';
COMMENT ON COLUMN payment_attempts.error_category IS 'Why a DECLINED, FAILED, or UNKNOWN attempt did not succeed.';

-- What an attempt is never changes, a provider transaction ID once learned is
-- kept, nothing returns to EXECUTING, only an executing attempt can come to
-- require customer action, and a finished attempt (SUCCEEDED, DECLINED, or
-- FAILED) is never updated again.
CREATE FUNCTION payment_attempts_reject_invalid_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.merchant_id, NEW.payment_intent_id, NEW.processor_account_id,
      NEW.operation_id, NEW.idempotency_record_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.merchant_id, OLD.payment_intent_id, OLD.processor_account_id,
      OLD.operation_id, OLD.idempotency_record_id, OLD.created_at) THEN
    RAISE EXCEPTION 'payment_attempts: the identity of an attempt cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status IN ('SUCCEEDED', 'DECLINED', 'FAILED') THEN
    RAISE EXCEPTION 'payment_attempts: a finished attempt cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.provider_transaction_id IS NOT NULL
     AND NEW.provider_transaction_id IS DISTINCT FROM OLD.provider_transaction_id THEN
    RAISE EXCEPTION 'payment_attempts: a provider transaction ID cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.status = 'EXECUTING' AND OLD.status <> 'EXECUTING' THEN
    RAISE EXCEPTION 'payment_attempts: an attempt cannot return to EXECUTING'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.status = 'REQUIRES_ACTION' AND OLD.status NOT IN ('EXECUTING', 'REQUIRES_ACTION') THEN
    RAISE EXCEPTION 'payment_attempts: only an executing attempt can require customer action'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER payment_attempts_restrict_update
BEFORE UPDATE ON payment_attempts
FOR EACH ROW
EXECUTE FUNCTION payment_attempts_reject_invalid_update();

-- Attempts are the payment history: deleting one would hide a charge or free
-- the intent for another attempt, so deletion is rejected for every statement.
CREATE FUNCTION payment_attempts_reject_delete() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'payment_attempts: % is not allowed', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER payment_attempts_restrict_delete
BEFORE DELETE OR TRUNCATE ON payment_attempts
FOR EACH STATEMENT
EXECUTE FUNCTION payment_attempts_reject_delete();
